// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Token token;

    function setUp() public {
        c = new C();
        token = new Token();
    }

    function testFuzz_property(address actor, address to, uint256 amount, uint256 count) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        vm.assume(count > 0 && count <= 8);
        address[] memory tos = new address[](count);
        uint256[] memory vs = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            tos[i] = to;
            vs[i] = amount;
        }
        vm.prank(actor);
        bool ok = c.transfer(actor, address(token), tos, vs);
        assertTrue(ok, "successful batched transfer must return true");
    }
}

contract Token {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
